#!/usr/bin/env python3
"""
train_asr_word_distill.py

Character-level Conformer Transducer training using chunk-level TextGrid
supervision produced by the word-level StreamingASR model.


---------------------------------------------------------
This script uses the same per-chunk RNNT loss strategy as
train_asr_aligned_librispeech_nobatch.py.  The key difference is the
source of the TextGrid files:

  * train_asr_aligned_librispeech_nobatch.py  →  Praat forced-alignment TextGrids
  * this script                               →  TextGrids generated by
                                                 generate_chunk_textgrids.py
                                                 (word model streaming output)

Because the word model commits words at chunk boundaries the xmax of every
word interval in the generated TextGrid equals the audio end-time of the
chunk where the word was first decoded.  The per-chunk RNNT loss therefore
directly supervises the character model to emit each word's character tokens
in the same temporal chunk as the word model — a form of chunk-level
knowledge distillation without requiring explicit soft targets.

Loss (per sample)
-----------------
For each encoder chunk c:

  logits  = joint(enc_c, dec_prefix_c)       shape [1, T_c, U_c+1, V]
  loss_c  = RNNT(logits, toks_c)             if U_c > 0
           = -sum(log P(blank | t, 0))       if U_c == 0   (blank supervision)

  loss = mean over chunks with T_c > 0

Fallback: samples whose TextGrid is missing fall back to standard
full-sequence RNNT.

Extra CLI argument
------------------
--textgrid_dir <path>   Directory containing TextGrid files that mirror the
                        LibriSpeech structure (produced by
                        generate_chunk_textgrids.py --output_dir <path>).
                        When omitted, TextGrids are looked up alongside
                        each .wav file (same behaviour as the Praat version).

Usage
-----
python train_asr_word_distill.py \\
    /home/streamalign/streamASR/hparams/chunk_streaming_librispeech.yaml \\
    [--textgrid_dir /home/datasets/LibriSpeech/chunk_textgrids_word_model]
"""

import argparse
import os
import sys
import traceback
import warnings
from collections import defaultdict
from dataclasses import dataclass
from pathlib import Path
from typing import List, Optional

warnings.filterwarnings(
    "ignore",
    message=".*Grid size.*will likely result in GPU under-utilization.*",
)

sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), ".."))

